# test_lvs_comprehensive.ps1
# Systematic LVS test: 25+ cases, both engines, real netlist.
# Run: .\test_lvs_comprehensive.ps1

param([string]$VygesBin = "$env:USERPROFILE\.cargo\bin\vyges-lvs.exe")

$ErrorActionPreference = "Stop"

